---@class UIBuffUpNode
---@field CardPar                       	UnityEngine.RectTransform                            
local UIBuffUpNode = Class("UIBuffUpNode")
function UIBuffUpNode:__init() 
    self._data = nil
    self._cb = nil
end

function UIBuffUpNode:__delete()
    self._data = nil
    self._cb = nil
end

function UIBuffUpNode:Awake()
end

function UIBuffUpNode:Start()
end

function UIBuffUpNode:Refresh(data, cb)
    if not data then 
        return
    end
    self._data = data
    self._cb = cb
    self:FillSelf()
end

function UIBuffUpNode:FillSelf()
    local name, path = QuestConfMgr:GetInstance():GetBuffNameAndImagePath(self._data)
    CfUtils.FillText(self.TxtName, name)
    CfUtils.FillImage(self.PlayerIcon, path)
    CfUtils.FillText(self.TxtContent, self:GetBuffDescs())
end

function UIBuffUpNode:GetBuffDescs()
    local str = ""
    local ids = CfUtils.Split(self._data.upBuff)
    if not ids then
        return str
    end
    for k, v in pairs(ids) do
        local vo = QuestConfMgr:GetInstance():GetQuestUpBuffVo(v) 
        if vo then
            str = str..vo.desc.."\n"
        end
    end
    return str
end

function UIBuffUpNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIBuffUpNode
